// ---- Routines ----

async function APRINT(obj) {
  if (hasFlag(obj, NARTICLEBIT) || hasFlag(obj, NOA) || hasFlag(obj, PLURALBIT)) {
    tell(" ");
  } else if (hasFlag(obj, VOWELBIT)) {
    tell(" an ");
  } else {
    tell(" a ");
  }
  return await DPRINT(obj);
}

async function TPRINT(obj) {
  if (hasFlag(obj, NARTICLEBIT)) {
    tell(" ");
  } else {
    tell(" the ");
  }
  return await DPRINT(obj);
}

async function TPRINT_PRSO() {
  return await TPRINT(g.PRSO);
}

async function TPRINT_PRSI() {
  return await TPRINT(g.PRSI);
}

async function ARPRINT(obj) {
  await APRINT(obj);
  tell(S(g.PERIOD));
  return true;
}

async function TRPRINT(obj) {
  await TPRINT(obj);
  tell(S(g.PERIOD));
  return true;
}

async function IS_ARE_PRINT(obj) {
  if (hasFlag(obj, NARTICLEBIT)) {
    tell(" ");
  } else {
    tell(" the ");
  }
  await DPRINT(obj);
  if (hasFlag(obj, PLURALBIT)) {
    tell(" are ");
    return true;
  } else {
    tell(" is ");
    return true;
  }
}

async function GO() {
  restart: for (;;) {
    g.WIDTH = getb(0, 33);
    if (s16(g.WIDTH) > s16(76)) {
      g.WIDE = true;
    } else {
      putProp(FROST_ROOM, P.SDESC, "Whiteness");
    }
    putb(g.P_LEXV, 0, 59);
    g.WINNER = PROTAGONIST;
    g.HERE = STARTING_ROOM;
    await V_$REFRESH();
    tell("\nUntied Press International\n\n  PUNSTER (UPI) - Citizens of the little town of Punster have recently been victimized by a series of strange happenings which have ground local businesses to a halt and played havoc with everyday life.\n  The wide-spread plague seems to be focused on the area of language itself. In some cases, what were once simple actions to perform now require the use of old, time-worn phrases.\n  In other cases, objects and even citizens have been transformed overnight into strange mutations of their previous selves.\n  A man-on-the-street interview conducted by this reporter proved fruitless. Two local farmers asked for their opinions of the situation said they couldn't make head or tail of it, and made no further statement.\n  The mayor of Punster, whose administration has been widely viewed as being paralyzed and corrupted by the plague, could not be reached for comment.\n  Meanwhile, a Citizens' Action Committee was recently formed to probe for ways to restore the town of Punster to its happily mundane condition.\n\n[Reporter's Note: This story was compiled with help from whoever it was\nwho untied me so I could type out this story.]\n");
    await GET_KEY();
    await V_$REFRESH();
    await V_VERSION();
    crlf();
    await V_LOOK();
    await MAIN_LOOP();
    continue restart;
  }
}

async function GET_KEY() {
  let x = 0;
  tell("\n[Press any key to begin.]\n");
  g.DATELINE = false;
  x = await readChar(1);
  return true;
}

async function MAIN_LOOP() {
  let trash = 0;
  for (;;) {
    trash = await MAIN_LOOP_1();
  }
}

async function MAIN_LOOP_1() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = 0, ptbl = 0, obj1 = 0, tmp = 0, onum = 0;
  cnt = 0;
  obj = false;
  ptbl = true;
  if (g.P_WON = await PARSER()) {
    icnt = get(g.P_PRSI, P_MATCHLEN);
    ocnt = get(g.P_PRSO, P_MATCHLEN);
    if (g.P_IT_OBJECT && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
      tmp = false;
      loop1: for (;;) {
        if (s16(cnt = cnt + 1) > s16(icnt)) {
          break loop1;
        } else {
          if (eq(get(g.P_PRSI, cnt), IT)) {
            put(g.P_PRSI, cnt, g.P_IT_OBJECT);
            tmp = true;
            break loop1;
          }
        }
      }
      if (!tmp) {
        cnt = 0;
        loop2: for (;;) {
          if (s16(cnt = cnt + 1) > s16(ocnt)) {
            break loop2;
          } else {
            if (eq(get(g.P_PRSO, cnt), IT)) {
              put(g.P_PRSO, cnt, g.P_IT_OBJECT);
              break loop2;
            }
          }
        }
      }
      cnt = 0;
    }
    onum = getb(g.P_SYNTAX, P_SBITS) & P_SONUMS;
    num = (ocnt == 0) || ((icnt == 0) && (onum == 2)) ? 0 : (s16(ocnt) > s16(1) ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (s16(icnt) > s16(1) ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
    if (!obj && (icnt == 1)) {
      obj = get(g.P_PRSI, 1);
    }
    if (g.PRSA == V.WALK) {
      v_ = await PERFORM_PRSA(g.PRSO);
    } else if (num == 0) {
      if ((getb(g.P_SYNTAX, P_SBITS) & P_SONUMS) == 0) {
        v_ = await PERFORM_PRSA();
        g.PRSO = false;
      } else if ((obj == PAN_OF_KEYS) && (g.PRSA == V.TAKE) && eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL, W.EVERYTHING)) {
        g.CLOCK_WAIT = true;
        await WASTES();
        await STOP();
      } else if (isVerb(V.NO_VERB)) {
        await RECOGNIZE();
        v_ = false;
        await STOP();
      } else if (isVerb(V.TAKE_UNDER)) {
        tell("You can't use \"all\" that way.\n");
      } else {
        tell("There isn't anything to ");
        tmp = get(g.P_ITBL, P_VERBN);
        if (isVerb(V.TELL)) {
          tell("talk to");
        } else if (g.P_OFLAG || g.P_MERGED) {
          printB(get(tmp, 0));
        } else {
          await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
        }
        tell("!\n");
        v_ = false;
        await STOP();
      }
    } else {
      g.P_NOT_HERE = 0;
      g.P_MULT = false;
      if (s16(num) > s16(1)) {
        g.P_MULT = true;
      }
      tmp = false;
      loop3: for (;;) {
        if (s16(cnt = cnt + 1) > s16(num)) {
          if (s16(g.P_NOT_HERE) > s16(0)) {
            tell("[The ");
            if (!(g.P_NOT_HERE == num)) {
              tell("other ");
            }
            tell("object");
            if (!(g.P_NOT_HERE == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(g.P_NOT_HERE == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.]\n");
          } else if (!tmp) {
            await REFERRING();
          }
          break loop3;
        } else {
          if (ptbl) {
            obj1 = get(g.P_PRSO, cnt);
          } else {
            obj1 = get(g.P_PRSI, cnt);
          }
          g.PRSO = ptbl ? obj1 : obj;
          g.PRSI = ptbl ? obj : obj1;
          if ((s16(num) > s16(1)) && (g.SCENE == HAZING || g.SCENE == AISLE) && !(eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL, W.EVERYTHING))) {
            g.CLOCK_WAIT = true;
            await PREGNANT();
            break loop3;
          } else if ((s16(num) > s16(1)) || eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL, W.EVERYTHING)) {
            if (await DONT_ALL(obj1)) {
              continue loop3;
            } else {
              if (obj1 == IT) {
                await DPRINT(g.P_IT_OBJECT);
              } else if (obj1 == HIM) {
                await DPRINT(g.P_HIM_OBJECT);
              } else if (obj1 == HER) {
                await DPRINT(g.P_HER_OBJECT);
              } else {
                await DPRINT(obj1);
              }
              tell(": ");
            }
          }
          tmp = true;
          v_ = await PERFORM_PRSA(g.PRSO, g.PRSI);
          if (v_ == M_FATAL) {
            break loop3;
          }
        }
      }
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
    if ((await CLOCKER_VERB$()) && !(isVerb(V.TELL)) && g.P_WON) {
      v_ = await apply(getProp(g.HERE, P.ACTION), M_END);
    }
  } else {
    g.P_CONT = false;
  }
  if (g.P_WON) {
    if (isVerb(V.WAIT) && g.DONT_FLAG) {
    } else if (await CLOCKER_VERB$()) {
      v_ = await CLOCKER();
    }
    g.P_NUMBER = 0;
    await STATUS_LINE();
    g.PRSA = false;
    g.PRSO = false;
    return g.PRSI = false;
  } else {
    return false;
  }
}

async function DONT_ALL(obj1) {
  let l = loc(obj1);
  if (obj1 == NOT_HERE_OBJECT) {
    g.P_NOT_HERE = g.P_NOT_HERE + 1;
    return true;
  } else if (isVerb(V.TAKE) && g.PRSI && !(loc(g.PRSO) == g.PRSI)) {
    return true;
  } else if (!(await ACCESSIBLE$(obj1))) {
    return true;
  } else if (g.P_GETFLAGS == P_ALL) {
    if (g.PRSI && (g.PRSO == g.PRSI)) {
      return true;
    } else if (isVerb(V.TAKE)) {
      if (!(hasFlag(obj1, TAKEBIT)) && !(hasFlag(obj1, TRYTAKEBIT))) {
        return true;
      } else if (!(l == g.WINNER || l == g.HERE || l == g.PRSI) && !(l == loc(g.WINNER))) {
        if (hasFlag(l, SURFACEBIT) && !(hasFlag(l, TAKEBIT))) {
          return false;
        } else {
          return true;
        }
      } else if (!g.PRSI && (await HELD$(g.PRSO))) {
        return true;
      } else if (obj1 == COMEUPPANCE || obj1 == UMBRAGE || obj1 == SHRIFT || obj1 == CAPE) {
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.DROP, V.PUT, V.PUT_ON, V.GIVE, V.SGIVE) && !(loc(obj1) == g.WINNER)) {
      return true;
    } else if (isVerb(V.PUT, V.PUT_ON) && !(loc(g.PRSO) == g.WINNER) && (await HELD$(g.PRSO, g.PRSI))) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CLOCKER_VERB$() {
  if (isVerb(V.VERSION, V.HINT, V.SCORE, V.SAVE, V.RESTORE, V.RESTART, V.QUIT, V.SCRIPT, V.UNSCRIPT, V.BRIEF, V.SUPER_BRIEF, V.VERBOSE, V.$VERIFY)) {
    return false;
  } else {
    return true;
  }
}

async function FAKE_ORPHAN(it_was_used = false) {
  let tmp = 0;
  await ORPHAN(g.P_SYNTAX, false);
  tmp = get(g.P_OTBL, P_VERBN);
  tell("[Be specific: Wh");
  if (it_was_used) {
    tell("at object");
  } else {
    tell("o");
  }
  tell(" do");
  if (g.DONT_FLAG) {
    tell("n't");
  }
  tell(" you want to ");
  if (tmp == 0) {
    tell("tell");
  } else if (getb(g.P_VTBL, 2) == 0) {
    printB(get(tmp, 0));
  } else {
    await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    putb(g.P_VTBL, 2, 0);
  }
  g.P_OFLAG = true;
  g.P_WON = false;
  await PREP_PRINT(getb(g.P_SYNTAX, P_SPREP1));
  tell("?]\n");
  return true;
}

async function NOW_PRSI_KLUDGE() {
  g.NOW_PRSI = false;
  return true;
}

async function PERFORM_PRSA(o = false, i = false) {
  return await PERFORM(g.PRSA, o, i);
}

async function PERFORM(a_, o = false, i = false) {
  let v_ = 0, oa = 0, oo = 0, oi = 0;
  oa = g.PRSA;
  oo = g.PRSO;
  oi = g.PRSI;
  g.PRSA = a_;
  if ((IT == o || IT == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_IT_OBJECT)) {
      if (IT == o) {
        o = g.P_IT_OBJECT;
      } else {
        i = g.P_IT_OBJECT;
      }
    } else {
      if (!i && !(isVerb(V.NO_VERB))) {
        await FAKE_ORPHAN(true);
      } else {
        await REFERRING();
      }
      return M_FATAL;
    }
  }
  if ((HIM == o || HIM == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_HIM_OBJECT)) {
      if (HIM == o) {
        o = g.P_HIM_OBJECT;
      } else {
        i = g.P_HIM_OBJECT;
      }
    } else {
      if (!i && !(isVerb(V.NO_VERB))) {
        await FAKE_ORPHAN();
      } else {
        await REFERRING(true);
      }
      return M_FATAL;
    }
  }
  if ((HER == o || HER == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_HER_OBJECT)) {
      if (HER == o) {
        o = g.P_HER_OBJECT;
      } else {
        i = g.P_HER_OBJECT;
      }
    } else {
      if (!i && !(isVerb(V.NO_VERB))) {
        await FAKE_ORPHAN();
      } else {
        await REFERRING(true);
      }
      return M_FATAL;
    }
  }
  g.PRSO = o;
  g.PRSI = i;
  if ((!(a_ == V.WALK) && (NOT_HERE_OBJECT == g.PRSO || NOT_HERE_OBJECT == g.PRSI) && (v_ = (await D_APPLY("Not Here", NOT_HERE_OBJECT_F.id))))) {
    g.P_WON = false;
  } else {
    o = g.PRSO;
    i = g.PRSI;
    await THIS_IS_IT(g.PRSI);
    await THIS_IS_IT(g.PRSO);
    if ((v_ = (await D_APPLY("Actor", getProp(g.WINNER, P.ACTION))))) {
    } else if (g.DONT_FLAG && (v_ = await DONT_F())) {
    } else if ((v_ = (await D_APPLY("M-Beg", getProp(loc(PROTAGONIST), P.ACTION), M_BEG)))) {
    } else if ((v_ = (await D_APPLY("Preaction", get(g.PREACTIONS, a_))))) {
    } else if ((i && (g.NOW_PRSI = true) && (v_ = (await D_APPLY("PRSI", getProp(i, P.ACTION)))))) {
    } else if ((o && !(a_ == V.WALK) && (await NOW_PRSI_KLUDGE()) && (v_ = (await D_APPLY("PRSO", getProp(o, P.ACTION)))))) {
    } else if (v_ = await D_APPLY(false, get(g.ACTIONS, a_))) {
    }
  }
  g.PRSA = oa;
  g.PRSO = oo;
  g.PRSI = oi;
  return v_;
}

async function D_APPLY(str, fcn, foo = false) {
  let res = 0;
  if (!fcn) {
    return false;
  } else {
    res = foo ? (await apply(fcn, foo)) : (await apply(fcn));
    return res;
  }
}

async function DEQUEUE(rtn) {
  if (rtn = await QUEUED$(rtn)) {
    return put(rtn, C_RTN, 0);
  } else {
    return false;
  }
}

async function QUEUED$(rtn) {
  let c_ = 0, e = 0;
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  for (;;) {
    if (c_ == e) {
      return false;
    } else if (eq(get(c_, C_RTN), rtn)) {
      if (get(c_, C_TICK) == 0) {
        return false;
      } else {
        return c_;
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

async function RUNNING$(rtn) {
  let c_ = 0, e = 0;
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  for (;;) {
    if (c_ == e) {
      return false;
    } else if (eq(get(c_, C_RTN), rtn)) {
      if ((get(c_, C_TICK) == 0) || (s16(get(c_, C_TICK)) > s16(1))) {
        return false;
      } else {
        return true;
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

async function QUEUE(rtn, tick) {
  let c_ = 0, e = 0, int = false;
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  loop1: for (;;) {
    if (c_ == e) {
      if (int) {
        c_ = int;
      } else {
        if (s16(g.C_INTS) < s16(C_INTLEN)) {
          tell("**Too many ints!**\n");
        }
        g.C_INTS = g.C_INTS - C_INTLEN;
        if (s16(g.C_INTS) < s16(g.C_MAXINTS)) {
          g.C_MAXINTS = g.C_INTS;
        }
        int = g.C_TABLE + g.C_INTS;
      }
      put(int, C_RTN, rtn);
      break loop1;
    } else if (eq(get(c_, C_RTN), rtn)) {
      int = c_;
      break loop1;
    } else if (get(c_, C_RTN) == 0) {
      int = c_;
    }
    c_ = c_ + C_INTLEN;
  }
  if (g.CLOCK_HAND && (s16(int) > s16(g.CLOCK_HAND))) {
    tick = -(tick + 3);
  }
  put(int, C_TICK, tick);
  return int;
}

async function CLOCKER() {
  let e = 0, tick = 0, rtn = 0, flg = false, q$ = false, owinner = 0;
  if (g.CLOCK_WAIT) {
    g.CLOCK_WAIT = false;
    return false;
  }
  g.CLOCK_HAND = g.C_TABLE + g.C_INTS;
  e = g.C_TABLE + C_TABLELEN;
  owinner = g.WINNER;
  g.WINNER = PROTAGONIST;
  for (;;) {
    if (g.CLOCK_HAND == e) {
      g.CLOCK_HAND = e;
      g.MOVES = g.MOVES + 1;
      g.WINNER = owinner;
      return flg;
    } else if (!(get(g.CLOCK_HAND, C_RTN) == 0)) {
      tick = get(g.CLOCK_HAND, C_TICK);
      if (s16(tick) < s16(-1)) {
        put(g.CLOCK_HAND, C_TICK, (-tick) - 3);
        q$ = g.CLOCK_HAND;
      } else if (!(tick == 0)) {
        if (s16(tick) > s16(0)) {
          tick = tick - 1;
          put(g.CLOCK_HAND, C_TICK, tick);
        }
        if (!(tick == 0)) {
          q$ = g.CLOCK_HAND;
        }
        if (!(s16(tick) > s16(0))) {
          rtn = get(g.CLOCK_HAND, C_RTN);
          if (tick == 0) {
            put(g.CLOCK_HAND, C_RTN, 0);
          }
          if (await apply(rtn)) {
            flg = true;
          }
          if (!q$ && !(get(g.CLOCK_HAND, C_RTN) == 0)) {
            q$ = true;
          }
        }
      }
    }
    g.CLOCK_HAND = g.CLOCK_HAND + C_INTLEN;
    if (!q$) {
      g.C_INTS = g.C_INTS + C_INTLEN;
    }
  }
}

