async function PICK_NEXT(tbl) {
  let cnt = 0, str = 0;
  cnt = get(tbl, 1);
  str = get(tbl, cnt);
  ++cnt;
  if (s16(cnt) > s16(get(tbl, 0))) {
    cnt = 2;
  }
  put(tbl, 1, cnt);
  return str;
}

async function PICK_ONE(tbl) {
  let length = 0, cnt = 0, rnd = 0, msg = 0, rfrob = 0;
  length = get(tbl, 0);
  cnt = get(tbl, 1);
  length = length - 1;
  tbl = tbl + 2;
  rfrob = tbl + (cnt * 2);
  rnd = random(length - cnt);
  msg = get(rfrob, rnd);
  put(rfrob, rnd, get(rfrob, 1));
  put(rfrob, 1, msg);
  cnt = cnt + 1;
  if (cnt == length) {
    cnt = 0;
  }
  put(tbl, 0, cnt);
  return msg;
}

