async function V_NO_VERB() {
  if (await NOUN_USED(ME, W.I)) {
    return await V_INVENTORY();
  } else if (g.TRANS_PRINTED) {
    return true;
  } else if (g.TURN_KLUDGE) {
    tell("It seems");
    await TPRINT_PRSO();
    tell(" doesn't change.\n");
    return true;
  } else if ((g.SCENE == AISLE) && (g.PRSO == DESSERTS) && ((await NOUN_USED(DESSERTS, W.DESSERT, W.DESSERTS)) || (await NOUN_USED(DESSERTS, W.DESS)) || (await ADJ_USED(DESSERTS, W.DESS)))) {
    g.REAL_AISLE = DESSERT_ROOM;
    await PERFORM(V.WALK_TO, AISLE);
    return true;
  } else if ((g.PRSO == START_OBJ) && (await NOUN_USED(START_OBJ, W.BEGIN, W.BEGINNING))) {
    await RE_BEGIN();
    return true;
  } else if (hasFlag(g.PRSO, SCENEBIT) && !(g.PRSO == g.SCENE)) {
    return await CANT_GET_THERE();
  } else if (hasFlag(g.PRSO, SCENEBIT)) {
    await PERFORM(V.WALK_TO, g.PRSO);
    return true;
  } else if (g.ORPHAN_FLAG) {
    if (g.ORPHAN_FLAG == CELLAR) {
      if (!(await VISIBLE$(g.PRSO))) {
        return await CANT_SEE(g.PRSO);
      } else {
        await PERFORM(V.BUY, g.PRSO);
        return true;
      }
    } else if (g.ORPHAN_FLAG == REST_TABLE) {
      if (!(await VISIBLE$(g.PRSO))) {
        return await CANT_SEE(g.PRSO);
      } else {
        await PERFORM(V.TURN_OBJECT_ON, REST_TABLE, g.PRSO);
        return true;
      }
    } else if ((g.ORPHAN_FLAG == NEEDLE) && (g.PRSO == NEEDLE)) {
      await PERFORM(V.SEARCH_OBJECT_FOR, HAYSTACK, g.PRSO);
      return true;
    } else if (g.ORPHAN_FLAG == SMOCK) {
      put(g.P_NAMW, 0, W.TALK);
      await PERFORM(V.MAKE_WITH, SMOCK, g.PRSO);
      return true;
    } else if (g.ORPHAN_FLAG == HATCHET) {
      await PERFORM(V.BURY, HATCHET, g.PRSO);
      return true;
    } else if ((g.ORPHAN_FLAG == SHOULDER) && (g.PRSO == SHOULDER)) {
      g.ORPHAN_FLAG = false;
      await UPDATE_SCORE();
      tell("The crowd eats it up.\n");
      return true;
    } else if (g.ORPHAN_FLAG == LOUIS_CHAIR) {
      await UPDATE_SCORE();
      if (g.PRSO == LOUIS_CHAIR) {
        (await ITALICIZE("Give"));
        clearFlag(LOUIS_CHAIR, TRYTAKEBIT);
        tell(" the ");
        await DPRINT(LOUIS_CHAIR);
        tell(" to you -- never! Well, yes, you may borrow it. I don't even want to ");
        (await ITALICIZE("know"));
        tell(" what you're going to use it for.\n");
        return true;
      } else if (g.PRSO == OLD_BOTTLE) {
        await PERFORM(V.TAKE, OLD_BOTTLE);
        return true;
      } else if (!(await VISIBLE$(g.PRSO))) {
        return await CANT_SEE(g.PRSO);
      } else if (hasFlag(g.PRSO, TAKEBIT)) {
        tell("It's yours for the taking.\n");
        return true;
      } else {
        return await IMPOSSIBLES();
      }
    } else {
      return await WASTES();
    }
  } else if (!(await VISIBLE$(g.PRSO))) {
    return await CANT_SEE(g.PRSO);
  } else if (g.P_CONT) {
    await PERFORM(V.TELL, g.PRSO);
    return true;
  } else {
    await PERFORM(V.EXAMINE, g.PRSO);
    return true;
  }
}

