async function V_WALK() {
  let av = 0, vehicle = 0, pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  av = loc(PROTAGONIST);
  if (!g.P_WALK_DIR) {
    await V_WALK_AROUND();
    return true;
  } else if ((g.PRSO == P.OUT) && (await IN_EXITABLE_VEHICLE$())) {
    return true;
  } else if ((g.PRSO == P.IN) && !(getPropAddr(g.HERE, P.IN)) && (vehicle = await FIND_IN(g.HERE, VEHBIT)) && !(await HELD$(vehicle))) {
    await PERFORM(V.BOARD, vehicle);
    return true;
  } else if (hasFlag(av, VEHBIT)) {
    return await NOT_GOING_ANYWHERE();
  } else if (pt = getPropAddr(g.HERE, g.PRSO)) {
    if (eq(pts = propSize(pt), UEXIT)) {
      return await GOTO(get(pt, REXIT));
    } else if (pts == NEXIT) {
      tell(S(get(pt, NEXITSTR)), "\n");
      return M_FATAL;
    } else if (pts == FEXIT) {
      if (rm = await apply(get(pt, FEXITFCN))) {
        return await GOTO(rm);
      } else {
        return M_FATAL;
      }
    } else if (pts == CEXIT) {
      if (globalValue(getb(pt, CEXITFLAG))) {
        return await GOTO(get(pt, REXIT));
      } else if (str = get(pt, CEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        tell(S(g.CANT_GO));
        return M_FATAL;
      }
    } else if (pts == DEXIT) {
      if (hasFlag(obj = get(pt, DEXITOBJ), OPENBIT)) {
        return await GOTO(get(pt, REXIT));
      } else if (str = get(pt, DEXITSTR)) {
        await THIS_IS_IT(obj);
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        await THIS_IS_IT(obj);
        (await DO_FIRST("open", obj));
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else {
    await V_WALK_AROUND();
    return M_FATAL;
  }
}

