async function RE_BEGIN() {
  if (g.HERE == STARTING_ROOM) {
    tell("You're already here.\n");
    return true;
  } else if (g.SCENE == COMEDY) {
    if (await RUNNING$(I_MATCH.id)) {
      await PERFORM(V.OFF, MATCH);
      return true;
    } else if ((await RUNNING$(I_BOB.id)) || (await RUNNING$(I_KNOCK.id)) || ((await RUNNING$(I_WIFE.id)) && !(g.WIFE_N == 0))) {
      tell("You can't bow out now; this moment is too crucial to the artistic integrity of the scene.\n");
      return true;
    }
  } else if (g.SCENE == AISLE) {
    if (await RUNNING$(I_BRAT.id)) {
      await DEQUEUE(I_BRAT.id);
      g.RESUME_BRAT = true;
    }
    if (await RUNNING$(I_ANTS.id)) {
      await DEQUEUE(I_ANTS.id);
      g.RESUME_ANTS = true;
    }
    if ((await HELD$(MUSSELS)) && !(hasFlag(MUSSELS, OLDBIT))) {
      remove(MUSSELS);
    }
  } else if (g.SCENE == JOAT) {
    if (await RUNNING$(I_FROST.id)) {
      tell("Such thoughts of escape from the cold evaporate into icy air.\n");
      return true;
    } else if (eq(getProp(PROTAGONIST, P.ACTION), PROTAG_JACKHAMMER_F.id)) {
      return false;
    }
    await DO_JACK();
  } else if ((g.SCENE == RESTAURANT) && ((await RUNNING$(I_PAN.id)) || (await RUNNING$(I_DEVICES.id)) || (await RUNNING$(I_PET_PEEVE.id)))) {
    tell("You can't leave at this crucial time!\n");
    return true;
  } else if (g.SCENE == HAZING) {
    if (await RUNNING$(I_CLIENT.id)) {
      tell("The stress involved from the situation prevents you from transporting.\n");
      return true;
    } else if ((await RUNNING$(I_DEAN.id)) || (await QUEUED$(I_DEAN.id))) {
      g.RESUME_DEAN = true;
    }
    await DE_LOUSE();
  } else if ((g.SCENE == DUELING) && (await RUNNING$(I_CLOCK.id))) {
    g.CLOCK_N = 0;
    await DEQUEUE(I_CLOCK.id);
  }
  await ROB(PROTAGONIST, g.HERE);
  putProp(g.SCENE, P.SCENE_ROOM, g.HERE);
  g.SCENE = false;
  move(PROTAGONIST, g.HERE);
  g.HERE = STARTING_ROOM;
  await V_$REFRESH();
  tell("You are surrounded by a swirling, blinding cloud. You feel your limbs going relaxed and your eyelids are buffeted with sand from the cloud.\n\n");
  g.OLD_HERE = false;
  await GOTO(STARTING_ROOM);
  await V_$REFRESH(true);
  crlf();
  await SHERIFF_ASKS();
  crlf();
  return true;
}

