async function PRINT_SPACES(cnt) {
  for (;;) {
    if (s16(cnt = cnt - 1) < s16(0)) {
      return true;
    } else {
      printC(32);
    }
  }
}

async function ITALICIZE(str, no_caps$ = false) {
  let len = 0, ptr = 2, char = 0;
  dirOut(D_SCREEN_OFF);
  dirOut(D_TABLE_ON, g.SLINE);
  tell(S(str));
  dirOut(D_TABLE_OFF);
  dirOut(D_SCREEN_ON);
  len = get(g.SLINE, 0) + 1;
  if (len == 1) {
    return true;
  } else if ((getb(0, 18) == 0) || (getb(0, 1) & 8)) {
    highlight(H_ITALIC);
    loop1: for (;;) {
      char = getb(g.SLINE, ptr);
      if (char == 32) {
        highlight(H_NORMAL);
        printC(32);
        highlight(H_ITALIC);
      } else {
        printC(char);
      }
      if (ptr == len) {
        break loop1;
      } else {
        ptr = ptr + 1;
      }
    }
    return highlight(H_NORMAL);
  } else if (no_caps$) {
    tell(S(str));
    return true;
  } else {
    for (;;) {
      char = getb(g.SLINE, ptr);
      if ((s16(char) > s16(96)) && (s16(char) < s16(123))) {
        char = char - 32;
      }
      printC(char);
      if (ptr == len) {
        return true;
      } else {
        ptr = ptr + 1;
      }
    }
  }
}

