async function TRANS_PRINT(object, old_word = false, no_cr = false) {
  let object_is_old = false;
  if (!(await VISIBLE$(object))) {
    return false;
  } else if (hasFlag(object, OLDBIT)) {
    object_is_old = true;
  }
  if (old_word) {
    setFlag(object, OLDBIT);
  } else {
    clearFlag(object, OLDBIT);
  }
  if ((object_is_old && !old_word) || (!object_is_old && old_word)) {
    if (object_is_old) {
      tell(S(getProp(object, P.OLD_TO_NEW)));
    } else if (getProp(object, P.NEW_TO_OLD)) {
      tell(S(getProp(object, P.NEW_TO_OLD)));
    }
    g.TRANS_PRINTED = true;
    if (!(hasFlag(object, TRANSFORMED))) {
      await UPDATE_SCORE();
    }
    setFlag(object, TRANSFORMED);
    if (no_cr) {
      return true;
    }
    crlf();
    if (!(isVerb(V.NO_VERB, V.SET, V.HAIR)) && !(g.PRSO == CLIENT)) {
      crlf();
    }
    return true;
  } else {
    return false;
  }
}

