async function V_HINT() {
  let chr = 0, maxq = 0, q = false;
  restart: for (;;) {
    if (g.HERE == STARTING_ROOM) {
      tell("You must be in one of the scenarios to ask for hints.\n");
      return true;
    } else if (g.HINTS_OFF) {
      await PERFORM(V.HINTS_NO, ROOMS);
      return true;
    } else if (!g.HINT_WARNING) {
      g.HINT_WARNING = true;
      tell("[Warning: It is recognized that the temptation for help may at times be so exceedingly strong that you might fetch hints prematurely. Therefore, you may at any time during the story type HINTS OFF, and this will disallow the seeking out of help for the present session of the story. If you still want a hint now, indicate HINT.]\n");
      return true;
    }
    bufOut(false);
    maxq = get(g.HINT_TBL, 0);
    await INIT_HINT_SCREEN();
    cursorSet(5, 1);
    g.CUR_POS = 0;
    await PUT_UP_QUESTIONS(1);
    g.CUR_POS = getProp(g.SCENE, P.SCENE_CUR);
    g.QUEST_NUM = g.CUR_POS + 1;
    await NEW_CURSOR();
    loop1: for (;;) {
      chr = await readChar(1);
      if (chr == 81 || chr == 113) {
        q = true;
        break loop1;
      } else if (chr == 78 || chr == 110) {
        if (g.QUEST_NUM == maxq) {
        } else {
          await ERASE_CURSOR();
          g.CUR_POS = g.CUR_POS + 1;
          g.QUEST_NUM = g.QUEST_NUM + 1;
          await NEW_CURSOR();
        }
      } else if (chr == 80 || chr == 112) {
        if (g.QUEST_NUM == 1) {
        } else {
          await ERASE_CURSOR();
          g.CUR_POS = g.CUR_POS - 1;
          g.QUEST_NUM = g.QUEST_NUM - 1;
          await NEW_CURSOR();
        }
      } else if (chr == 13 || chr == 10) {
        putProp(g.SCENE, P.SCENE_CUR, g.CUR_POS);
        await DISPLAY_HINT(g.QUEST_NUM);
        break loop1;
      }
    }
    if (!q) {
      continue restart;
    }
    putProp(g.SCENE, P.SCENE_CUR, g.CUR_POS);
    splitWindow(0);
    clearScreen(-1);
    bufOut(true);
    await V_$REFRESH();
    tell("\nBack to the story...\n");
    return true;
  }
}

