async function DISPLAY_HINT(n_) {
  let h = 0, mx = 0, cnt = 2, chr = 0, flg = true;
  splitWindow(0);
  clearScreen(-1);
  splitWindow(3);
  setWindow(S_WINDOW);
  cursorSet(1, 1);
  await INVERSE_LINE();
  (await CENTER_LINE(1, "INVISICLUES (tm)", 16));
  cursorSet(3, 1);
  await INVERSE_LINE();
  if (g.WIDE) {
    tell(" ");
  }
  (await LEFT_LINE(3, "RETURN = see new hint"));
  (await RIGHT_LINE(3, "Q = see hint menu", 17));
  highlight(H_BOLD);
  h = get(g.HINT_TBL, n_);
  await CENTER_LINE(2, get(h, 1));
  highlight(H_NORMAL);
  mx = get(h, 0);
  setWindow(S_TEXT);
  crlf();
  for (;;) {
    if (flg) {
      tell(" -> ");
      flg = false;
    }
    chr = await readChar(1);
    if (chr == 81 || chr == 113) {
      return true;
    } else if (chr == 13 || chr == 10) {
      if (s16(cnt) > s16(mx)) {
      } else {
        flg = true;
        tell(S(get(h, cnt)));
        crlf();
        crlf();
        cnt = cnt + 1;
        if (s16(cnt) > s16(mx)) {
          flg = false;
          tell("[That's all folks!]\n");
        }
      }
    }
  }
}

async function PUT_UP_QUESTIONS(st) {
  let mxq = 0, mxl = 0;
  mxq = get(g.HINT_TBL, 0);
  mxl = getb(0, 32) - 1;
  for (;;) {
    if (s16(st) > s16(mxq)) {
      return true;
    } else {
      cursorSet(get(g.LINE_TABLE, g.CUR_POS), get(g.COLUMN_TABLE, g.CUR_POS) - 1);
    }
    tell(" ", S(get(get(g.HINT_TBL, st), 1)));
    g.CUR_POS = g.CUR_POS + 1;
    g.QUEST_NUM = g.QUEST_NUM + 1;
    st = st + 1;
  }
}

async function INIT_HINT_SCREEN() {
  let wid = 0, len = 0;
  wid = getb(0, 33);
  splitWindow(0);
  clearScreen(-1);
  splitWindow(getb(0, 32) - 1);
  setWindow(S_WINDOW);
  bufOut(false);
  cursorSet(1, 1);
  await INVERSE_LINE();
  cursorSet(2, 1);
  await INVERSE_LINE();
  cursorSet(3, 1);
  await INVERSE_LINE();
  (await CENTER_LINE(1, "INVISICLUES (tm)", 16));
  (await LEFT_LINE(2, " N = next"));
  (await RIGHT_LINE(2, "P = previous", 12));
  (await LEFT_LINE(3, " RETURN = See hint"));
  return (await RIGHT_LINE(3, "Q = Resume story", 16));
}

async function CENTER_LINE(ln, str, len = 0, inv = true) {
  if (len == 0) {
    dirOut(D_TABLE_ON, g.SLINE);
    tell(S(str));
    dirOut(D_TABLE_OFF);
    len = get(g.SLINE, 0);
  }
  cursorSet(ln, div(getb(0, 33) - len, 2));
  if (inv) {
    highlight(H_INVERSE);
  }
  tell(S(str));
  if (inv) {
    return highlight(H_NORMAL);
  } else {
    return false;
  }
}

async function LEFT_LINE(ln, str, inv = true) {
  cursorSet(ln, 1);
  if (inv) {
    highlight(H_INVERSE);
  }
  tell(S(str));
  if (inv) {
    return highlight(H_NORMAL);
  } else {
    return false;
  }
}

async function RIGHT_LINE(ln, str, len = 0, inv = true) {
  if (len == 0) {
    dirOut(3, g.SLINE);
    tell(S(str));
    dirOut(-3);
    len = get(g.SLINE, 0);
  }
  cursorSet(ln, getb(0, 33) - len);
  if (inv) {
    highlight(H_INVERSE);
  }
  tell(S(str));
  if (inv) {
    return highlight(H_NORMAL);
  } else {
    return false;
  }
}

async function HAZING_F() {
  if (await NOUN_USED(HAZING, W.CLEARING)) {
    g.REAL_HAZING = CLEARING;
  } else if (await NOUN_USED(HAZING, W.SHORE)) {
    g.REAL_HAZING = SHORE;
  } else if (await NOUN_USED(HAZING, W.FACTORY)) {
    g.REAL_HAZING = FACTORY;
  } else if ((await NOUN_USED(HAZING, W.STOCK)) || (await ADJ_USED(HAZING, W.JEAN, W.STOCK))) {
    if (g.HERE == CLOUD_ROOM) {
      tell("The stalk only quivers slightly underfoot. Not being in full view of the stalk, you can't seem to transform it.\n");
      return true;
    } else if ((g.HERE == STALK_ROOM) && (await RUNNING$(I_CLIENT.id))) {
      tell("The ");
      await DPRINT(CLIENT);
      tell(" deflects your thoughts of the");
      if (g.PRSO == HAZING) {
        await PRSO_PRINT();
      } else {
        await PRSI_PRINT();
      }
      tell(".\n");
      return true;
    } else if (g.HERE == STALK_ROOM) {
      tell("A swift cloud of dust blows up from the trackless wastes into your face, causing you to bring your fists to your eyes like binoculars. After much rubbing, your vision, though blurry at first, returns to reveal familiar surroundings...\n\n");
      await GOTO(STOCK_ROOM);
      return true;
    }
    g.REAL_HAZING = STOCK_ROOM;
  } else if ((await NOUN_USED(HAZING, W.STALK, W.BEANSTALK)) || (await ADJ_USED(HAZING, W.BEAN, W.STALK))) {
    if (loc(CLIENT) == g.HERE) {
      tell("The ");
      await DPRINT(CLIENT);
      tell(" must've read your thoughts and he must not have enjoyed what he read, since he angrily snaps a pair of jeans at you, and your thoughts stray from");
      await TRPRINT(JEAN_STOCK);
      return true;
    }
    if (g.HERE == STOCK_ROOM) {
      if (!(hasFlag(STALK_ROOM, TOUCHBIT))) {
        await UPDATE_SCORE();
      }
      tell("The mile-high stack of jeans slowly leans heavily into your direction and as it passes the point of no return in a chaos of color, fabric and rivets, all the jeans come tumbling down upon your head,");
      if ((await HELD$(ICICLE)) || eq(loc(PROTAGONIST), ICICLE)) {
        tell(" knocking the ");
        await DPRINT(ICICLE);
        tell(" away and");
        move(ICICLE, STOCK_ROOM);
      }
      tell(" burying you completely in blackness.\n\nWhen you come to, it's in a new environment...\n\n");
      move(PROTAGONIST, g.HERE);
      await GOTO(STALK_ROOM);
      return true;
    }
    g.REAL_HAZING = STALK_ROOM;
  } else if ((await NOUN_USED(HAZING, W.CLOUD)) || (await ADJ_USED(HAZING, W.CLOUD))) {
    g.REAL_HAZING = CLOUD_ROOM;
  }
  if (!g.REAL_HAZING || isVerb(V.NO_VERB, V.TELL) || ((await DONT_HANDLE(HAZING)) && !(isVerb(V.WALK_TO)))) {
    return false;
  } else if (isVerb(V.WALK_TO)) {
    if (g.HERE == g.REAL_HAZING) {
      tell(S(g.ARRIVED));
      return true;
    } else if (g.HERE == CLOUD_ROOM) {
      if (g.REAL_HAZING == STALK_ROOM) {
        await DO_WALK(P.DOWN);
        return true;
      }
      tell("Can't get there from here.\n");
      return true;
    } else if (g.REAL_HAZING == CLOUD_ROOM) {
      if (g.HERE == STALK_ROOM) {
        await DO_WALK(P.UP);
        return true;
      } else {
        tell("All that's on a whole different plane of existence. The departure point of that existence is the stock room.\n");
        return true;
      }
    } else if (g.HERE == STALK_ROOM) {
      if (g.REAL_HAZING == CLOUD_ROOM) {
        return await DO_WALK(P.UP);
      } else {
        tell("It's on a different plane of existence.\n");
        return true;
      }
    } else if ((g.HERE == CLEARING) && !(hasFlag(g.REAL_HAZING, TOUCHBIT))) {
      tell("You don't know the way there.\n");
      return true;
    } else if ((g.REAL_HAZING == FACTORY) && !(loc(PROTAGONIST) == ICICLE)) {
      if (!(loc(LINES) == SHORE)) {
        tell(S(g.DONT_KNOW_WHERE));
        return true;
      } else if (!(hasFlag(FACTORY, TOUCHBIT))) {
        tell("You follow in the precise direction of the shepherd. It's trecherous going, since you're travelling over dill and hail -- that is, pickles strewn along the paths, and ice chunks hurling from the sky. You eventually come upon an out-of-the-way spot along the now quite polluted river. It's a prime location for such a flagrant violator of anti-pollution laws as the old factory, between whose grimy gates you suspiciously enter.\n\n");
        return await GOTO(FACTORY);
      } else if (g.HERE == STOCK_ROOM) {
        tell("You walk into the factory.\n\n");
        return await GOTO(FACTORY);
      } else {
        tell("You travel over hill and dale...\n\n");
        return await GOTO(FACTORY);
      }
    } else if ((g.REAL_HAZING == STOCK_ROOM) && !(eq(loc(PROTAGONIST), ICICLE)) && !(g.HERE == CLEARING)) {
      if (!(hasFlag(FACTORY, TOUCHBIT))) {
        tell(S(g.DONT_KNOW_WHERE));
        return true;
      } else if (g.HERE == FACTORY) {
      } else if (g.HERE == SHORE) {
        tell("You follow the direction of the shepherd.\n\n");
      }
      return await GOTO(STOCK_ROOM);
    } else if (g.REAL_HAZING == STALK_ROOM) {
      return await CANT_GET_THERE();
    } else if ((g.REAL_HAZING == CLEARING) && !g.ELF_TOLD) {
      tell("You don't know the way back.\n");
      return true;
    } else if (!(loc(PROTAGONIST) == ICICLE) && ((g.REAL_HAZING == CLEARING) || ((g.REAL_HAZING == SHORE || g.REAL_HAZING == FACTORY || g.REAL_HAZING == STOCK_ROOM) && (g.HERE == CLEARING)))) {
      tell("You'd need transportation to get there.\n");
      return true;
    } else if (loc(PROTAGONIST) == ICICLE) {
      move(ICICLE, g.REAL_HAZING);
      if (g.REAL_HAZING == CLEARING) {
        tell("With all the enthusiasm of a child actor in a Steven Spielberg movie with a percentage, you pedal away...");
      } else {
        tell("Pedaling madly away, you ride like the wind...");
      }
      crlf();
      crlf();
      return await GOTO(g.REAL_HAZING);
    } else {
      tell("You go there.\n\n");
      return await GOTO(g.REAL_HAZING);
    }
  } else if (HAZING == g.WINNER) {
    await RECOGNIZE();
    return true;
  } else if (!(g.HERE == g.REAL_HAZING)) {
    return (await CANT_SEE(false, "such place"));
  } else {
    return false;
  }
}

