async function JOAT_F() {
  if ((loc(JOAT) == GLOBAL_OBJECTS) && (await VISIBLE$(g.JACK_IS))) {
    await CHANGE_OBJECT(JOAT, g.JACK_IS);
    return true;
  } else if (isVerb(V.RUB, V.TOUCH) && (loc(BALL_OF_FUR) == JOAT)) {
    await CHANGE_OBJECT(JOAT, BALL_OF_FUR);
    return true;
  } else if (isVerb(V.WEAR)) {
    await CHANGE_OBJECT(JOAT, SLEEVES);
    return true;
  } else if (isVerb(V.OPEN)) {
    await CHANGE_OBJECT(JOAT, PIECE_OF_METAL);
    return true;
  } else if (isVerb(V.ON, V.SET, V.CLOSE)) {
    return await BE_MORE_SPECIFIC();
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    tell("You can see right away it's versatile.\n\nIt's sort of squarish, but sort of longish too");
    if (loc(BALL_OF_FUR) == JOAT) {
      tell(" and has a fluffy ball of cottony fur at one end");
    }
    tell(". Its surface is made of thick cloth, except for one edge which is a long piece of metal that looks as if it can be pulled out.\n\nOn three different sides of the strange contraption you can see a hand crank, a water faucet, and an electrical switch. As if all that wasn't enough, there is also a pair of sleeves sticking out of the thing.\n");
    return true;
  } else {
    return false;
  }
}

async function CHANGE_JACK(obj = false) {
  if (!g.JACK_IS) {
    if (!(hasFlag(obj, PHRASEBIT))) {
      setFlag(obj, PHRASEBIT);
      await UPDATE_SCORE();
    }
    clearFlag(obj, INTEGRALBIT);
    setFlag(obj, TAKEBIT);
    g.JACK_IS = obj;
    move(obj, loc(JOAT));
    move(JOAT, LOCAL_GLOBALS);
    return true;
  } else if (!obj) {
    if (g.JACK_IS == FAUCET) {
      move(JOAT, loc(HOT_TUB));
    } else {
      move(JOAT, loc(g.JACK_IS));
    }
    setFlag(g.JACK_IS, INTEGRALBIT);
    clearFlag(g.JACK_IS, TAKEBIT);
    move(g.JACK_IS, JOAT);
    return g.JACK_IS = false;
  } else {
    return false;
  }
}

async function NO_JACK_HERE(obj, n1 = false, n2 = false, n3 = false) {
  let str = 0;
  str = getProp(obj, P.JACKDESC);
  if (await DONT_HANDLE(obj)) {
    return false;
  } else if ((await NOUN_USED(obj, n1, n2, n3)) && !g.JACK_IS) {
    tell("While the ");
    await DPRINT(JOAT);
    tell(" has the potential to be a ", S(str), ", it is not yet one.\n");
    return true;
  } else if (g.JACK_IS && !(g.JACK_IS == obj)) {
    return await CANT_SEE(false, str);
  } else {
    return false;
  }
}

